local _, ns = ...
local Translate = ns.Lore.Translate

Translate("deDE", "dun-morogh", {
	title = "Dun Morogh",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dun Morogh ist ein Land aus Schnee und Stein im Westen von Khaz Modan, der alten Heimat der {link:dwarves}Zwerge{/link}. Seine Gipfel sind die höchsten der {link:eastern-kingdoms}Östlichen Königreiche{/link}, und im größten von ihnen liegt {link:ironforge}Ironforge{/link}, die {link:capital-city}Hauptstadt{/link} des {link:kingdom-of-ironforge}Königreichs Ironforge{/link}. Auch die {link:gnomes}Gnome{/link} lebten einst hier, in der Stadt {link:gnomeregan}Gnomeregan{/link} unter den westlichen Hügeln. Zwischen den beiden Städten liegen gefrorene Seen, Kiefernwälder und eine einzige lange Straße durch den Schnee. Es ist ein hartes Land, und sein Volk ist stolz darauf.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:dwarves}Zwerge{/link} sagen, sie seien in vergangenen Zeitaltern aus dem Stein dieser Berge geformt worden und {link:ironforge}Ironforge{/link} sei ihre älteste Heimat. Vor langer Zeit wurden alle Zwerge von dort aus durch einen einzigen Hochkönig regiert. Als dieser König starb, zogen die Clans Bronzebeard, Wildhammer und {link:dark-iron-dwarves}Dunkeleisen{/link} um seinen Thron in den Krieg, und die Bronzebeards behielten den Berg. Die {link:gnomes}Gnome{/link} wurden die Nachbarn und Freunde der Zwerge, und sie errichteten {link:gnomeregan}Gnomeregan{/link} in den westlichen Vorbergen. Keine Chronik verzeichnet das Jahr, in dem eine der beiden Städte gegründet wurde.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Dun Morogh ist unsicherer, als es seit Menschengedenken war. Ein großer Teil des Heeres des Königs ist fern und dient der {link:alliance}Allianz{/link} in der Fremde, und die Gebirgsjäger, die geblieben sind, sind wenige. Die {link:troggs}Troggs{/link} sind aus den tiefen Orten hervorgequollen, und sie halten nun den Coldridgepass und die Gruben des {link:gol-bolar-quarry}Gol'bolar{/link} Steinbruchs. Die {link:frostmane-trolls}Trolle der Frostmane{/link} halten ihre Höhlen und Kämme im Westen. {link:gnomeregan}Gnomeregan{/link} ist verloren, und sein vergiftetes Volk irrt vor seinen Toren umher. Wendigos haben den altgedienten Bau gefüllt. Am beunruhigendsten von allem: Im Osten wurden Spione des {link:dark-iron-dwarves}Dunkeleisenclans{/link} gesehen, die Karten von Tunneln bei sich trugen, die bis unter {link:ironforge}Ironforge{/link} selbst führen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link}.{/b} Bergleute, Brauer, Widderzüchter und Gebirgsjäger; sie leben in {link:kharanos}Kharanos{/link}, in {link:brewnall-village}Brewnall{/link} und in den einsamen {link:camping}Lagern{/link} des Hochlands.
• {b}Die {link:gnomes}Gnome{/link} von {link:gnomeregan}Gnomeregan{/link}.{/b} Die Überlebenden ihrer gefallenen Stadt finden Zuflucht in Ironforge, und einige arbeiten in Kharanos daran, den angerichteten Schaden wiedergutzumachen.
• {b}Die {link:frostmane-trolls}Trolle der Frostmane{/link}.{/b} Sie halten Höhlen und Kämme im Westen und streiten mit den Zwergen um den Schnee.
• {b}Die {link:troggs}Troggs{/link}.{/b} Die Troggs der Rockjaw stiegen aus dem Inneren der Erde empor und greifen nun überall an, wo die Zwerge graben.
• {b}Die Wendigos und die Tiere.{/b} Wendigos, Bären, Eber und Schneeleoparden durchstreifen {link:razorfen-downs}die Hügel{/link}, und manche von ihnen sind zu kühn und zu groß geworden.
• {b}Die {link:dark-iron-dwarves}Dunkeleisen{/link}.{/b} Eine Schar von ihnen hält {link:ironband-s-compound}Ironbands Truppenlager{/link} im Osten, lauernd und wartend.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die drei Hämmer.{/b} Im Krieg der drei Clans hielten die Bronzebeards {link:ironforge}Ironforge{/link} und vertrieben ihre Rivalen. Ein Vertrag, der unter der Stadt aufbewahrt wird, verzeichnet, dass die Wildhammers den Frieden unterzeichneten und die {link:dark-iron-dwarves}Dunkeleisen{/link} nicht.
• {b}Der Zweite Krieg.{/b} Als die {link:horde}Horde{/link} Khaz Modan überrannte, hielt Ironforge selbst stand. Die {link:dwarves}Zwerge{/link} traten der {link:alliance}Allianz von Lordaeron{/link} bei und kämpften an der Seite der Menschheit, bis die Horde zerschlagen war.
• {b}Der Fall von {link:gnomeregan}Gnomeregan{/link}.{/b} Die {link:troggs}Troggs{/link} erhoben sich unter der Stadt der {link:gnomes}Gnome{/link}. Die Gnome kämpften, um sie zu vertreiben, doch die Waffe, die sie einsetzten, vergiftete die Stadt und viele aus ihrem eigenen Volk. Die Überlebenden flohen nach Ironforge.
• {b}Die Gegenwart.{/b} Nun stehen die Zwerge Troggs, Trollen und Dunkeleisen zugleich gegenüber, während die Hälfte ihrer Streitmacht fern im Krieg ist.]=],
		},
		{
			title = "Überlieferungen der Berge",
			text = [=[• Die Thunderbrews aus {link:kharanos}Kharanos{/link} und die Barleybrews aus {link:brewnall-village}Brewnall{/link} sind rivalisierende Brauerfamilien. Jede glaubt, das Bier der anderen tauge nur für Eber.
• Die {link:frostmane-trolls}Trolle der Frostmane{/link} ziehen auf den Kämmen über dem {link:iceflow-lake}Iceflowsee{/link} ein blasses Kraut namens Schimmerkraut, und sie verwenden es für ihre Rituale. Die {link:dwarves}Zwerge{/link} haben eine bessere Verwendung dafür gefunden: Starkbier.
• Die Gebirgsjäger von {link:ironforge}Ironforge{/link} schnitzen ihre Namen in die Schäfte ihrer Gewehre, damit man den Schnee dazu bringen kann zu verraten, wen er geholt hat.
• Diebe in Ironforge flüstern, dass die gepanzerten Dampfpanzer des Königs Erz und Edelsteine aus dem {link:gol-bolar-quarry}Gol'bolar{/link} Steinbruch auf einem seltsam umständlichen Weg befördern, und dass jemand ihn um ein wenig davon erleichtern sollte.]=],
		},
	},
})

Translate("deDE", "coldridge-valley", {
	title = "Das Coldridgetal",
	aliases = { "Coldridge" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Coldridgetal ist ein geschütztes Tal im Südwesten von {link:dun-morogh}Dun Morogh{/link}, auf allen Seiten von Bergen umschlossen. Neue Verteidiger von {link:ironforge}Ironforge{/link} kommen hierher, um in Anvilmar ihr Handwerk zu erlernen. Das Tal hat seinen Frieden verloren. {link:troggs}Troggs{/link} der Rockjaw überrannten das Lager im Westen und wimmeln durch {link:razorfen-downs}die Hügel{/link} am gefrorenen See. {link:frostmane-trolls}Trolle der Frostmane{/link} halten eine Höhle im Süden. Der einzige Weg hinaus, durch den Tunnel des Coldridgepasses, ist nun voller Troggs, und ein Gebirgsjäger hält an seinem Eingang Wache.]=],
		},
	},
})

Translate("deDE", "anvilmar", {
	title = "Anvilmar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Anvilmar ist eine tief in den Berghang gegrabene Wohnstätte am oberen Ende des Coldridgetals. Hier lehren die Ausbilder von {link:ironforge}Ironforge{/link} die Jungen zu kämpfen, zu beten und ihr Handwerk auszuüben, und Ausstatter geben ihnen warme Kleidung gegen die Kälte. Es ist auch eine Zuflucht. {link:gnomes}Gnome{/link}, die vor dem Gift von {link:gnomeregan}Gnomeregan{/link} flohen, haben in seinen Hallen Unterschlupf gefunden, und einige von ihnen zählen noch, was sie unterwegs verloren haben.]=],
		},
	},
})

Translate("deDE", "kharanos", {
	title = "Kharanos",
	aliases = { "Brauerei Donnerbräu" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kharanos ist die wichtigste Stadt von {link:dun-morogh}Dun Morogh{/link}, eine Ansammlung von Steinhäusern an der Straße zwischen {link:coldridge-valley}Coldridge{/link} und {link:ironforge}Ironforge{/link}. In ihrem Herzen steht die Brauerei Donnerbräu, berühmt in ganz Khaz Modan, deren Keller hoch mit Fässern voll Thunder Ale gestapelt sind. Das Gasthaus darin ist selten still. Gebirgsjäger erstatten hier Bericht, und {link:senir-whitebeard}Senir Whitebeard{/link} schreibt hier seine Berichte für den Senat von Ironforge. Zwei {link:gnomes}Gnome{/link} in der Stadt arbeiten an einer Maschine, von der sie hoffen, dass sie ihr Volk heilen wird.]=],
		},
	},
})

Translate("deDE", "steelgrill-s-depot", {
	title = "Steelgrills Depot",
	aliases = { "Steelgrill-Depot" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Steelgrills Depot steht gleich nordöstlich von {link:kharanos}Kharanos{/link}. Es ist die Werkstatt von {link:beldin-steelgrill}Beldin Steelgrill{/link}, dem besten Mechaniker für Belagerungsmaschinen in den Bergen, und ein Treffpunkt der Piloten der Belagerungsbrigade. Ihre gepanzerten Dampfpanzer tragen Namen wie Jetsteam und Trollplow, und ihre Piloten prahlen mit ihnen, wie andere {link:dwarves}Zwerge{/link} mit Widdern prahlen. Im Depot hört man viel von dem, was auf den Straßen vor sich geht, und es war der Bericht eines Gebirgsjägers hier, der zuerst die Aufmerksamkeit auf ein seltsames Lagerfeuer oberhalb von {link:gol-bolar-quarry}Gol'bolar{/link} lenkte.]=],
		},
	},
})

Translate("deDE", "the-grizzled-den", {
	title = "Der altgediente Bau",
	aliases = { "Altgedienter Bau" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der altgediente Bau ist eine Höhle in den Hügeln westlich von {link:kharanos}Kharanos{/link}. Ihre Tunnel waren einst eine reiche Erzquelle, und die Bergleute von Kharanos arbeiteten dort. Dann breiteten sich die Wendigos aus ihren eigenen Höhlen aus und füllten sie. Die Bergleute flohen und ließen ihre Lieferungen zurück. Ein Gebirgsjäger namens Cornelius ging hinein, um zu erfahren, wie schlimm es stand, und kam nie wieder heraus. Tief im Inneren haust ein lauter und wilder Wendigo namens Frosthowl.]=],
		},
	},
})

Translate("deDE", "chill-breeze-valley", {
	title = "Chillbreezetal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Chillbreezetal öffnet sich im Westen von {link:dun-morogh}Dun Morogh{/link}, zwischen {link:kharanos}Kharanos{/link} und den Hügeln von {link:gnomeregan}Gnomeregan{/link}. Sein östlicher Teil wird viel bereist, denn die Straße vom Coldridgepass führt hindurch. Nur wenige gehen freiwillig in seine stilleren Winkel. Dort hat ein großer Wendigo namens Old Icebeard eine Höhle, und er schleppte einst die ganze Fleischkammer des Fallenstellers Tundra MacGrann fort, der mit einem schlimmen Bein und leerem Magen in der Nähe lagert.]=],
		},
	},
})

Translate("deDE", "brewnall-village", {
	title = "Brewnall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Brewnall liegt am Westufer des Iceflowsees. Es ist die Heimat der Familie Barleybrew, Brauer, die ohne Furcht und manchmal ohne Erfolg experimentieren. Ihr Evershine brennt so heiß, dass Belagerungspiloten es in ihre Kessel gießen. Die Barleybrews haben nichts für die Thunderbrews aus {link:kharanos}Kharanos{/link} übrig, und sie sind sich für ein wenig Unfug im Keller ihrer Rivalen nicht zu schade. Fischer arbeiten neben ihnen am See, und die {link:frostmane-trolls}Trolle der Frostmane{/link} beobachten sie aus dem Südwesten.]=],
		},
	},
})

Translate("deDE", "iceflow-lake", {
	title = "Iceflowsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Iceflowsee erstreckt sich über den Norden von {link:dun-morogh}Dun Morogh{/link}, westlich von {link:ironforge}Ironforge{/link}, und ist einen großen Teil des Jahres zugefroren. Ein Eisstrom fließt von der Brücke nördlich von {link:kharanos}Kharanos{/link} zu ihm hinab. Wölfe jagen auf der Insel in seiner Mitte. Die Fischer von {link:brewnall-village}Brewnall{/link} schlagen Löcher ins Eis und warten tagelang über ihren Leinen, und sie verfluchen die Wendigos, die das Wenige stehlen, das sie fangen.]=],
		},
	},
})

Translate("deDE", "frostmane-hold", {
	title = "Höhle der Frostmane",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Höhle der Frostmane ist die große Höhle der {link:frostmane-trolls}Trolle der Frostmane{/link}, südwestlich von {link:brewnall-village}Brewnall{/link}. Kopfjäger, Fellschinder, Schneeläufer und Schattenwirker hausen dort in einer Zahl, die selbst den {link:dwarves}Zwerg{/link} erschreckte, der ausgesandt wurde, um sie zu zählen. Die Höhle ist das Herz der Macht der Frostmane in {link:dun-morogh}Dun Morogh{/link}. Was die {link:trolls}Trolle{/link} darin planen, haben die Zwerge zu erfahren versucht, und ihre Berichte haben im Senat ebenso viel Unruhe gestiftet wie im Schnee.]=],
		},
	},
})

Translate("deDE", "shimmer-ridge", {
	title = "Schimmergrat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schimmergrat ist eine Kette hoher Hügel im Norden von {link:dun-morogh}Dun Morogh{/link}, nahe dem {link:iceflow-lake}Iceflowsee{/link} und westlich der Tore von {link:ironforge}Ironforge{/link}. Die {link:frostmane-trolls}Trolle der Frostmane{/link} haben dort Lager, durch eine Brücke verbunden, und ihre Seher pflegen dort Körbe mit Schimmerkraut. Das Kraut spielt eine Rolle in ihren Riten. Für die Brauer von {link:brewnall-village}Brewnall{/link} hat es einen anderen Zweck, und sie bezahlen gut jeden, der den Grat erklimmt, um es zu stehlen.]=],
		},
	},
})

Translate("deDE", "gates-of-gnomeregan", {
	title = "Tore von Gnomeregan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nördlich von {link:brewnall-village}Brewnall{/link} steigen {link:razorfen-downs}die Hügel{/link} des westlichen {link:dun-morogh}Dun Morogh{/link} zu den Toren von {link:gnomeregan}Gnomeregan{/link} an. Einst war dies ein geschäftiges Land voller Maschinen und Dörfer der {link:gnomes}Gnome{/link}. Nun stehen die Pumpen und Filter zerbrochen da, und die Gnome, die geblieben sind, sind vergiftet, krank und feindselig und irren vor den Türen der Stadt umher, die sie nicht retten konnten. Unter ihnen verbirgt sich ein verkleideter zwergischer Spion mit zwielichtigen Absichten. Gnome, die flohen, sagen, dass hier noch kostbare Aufzeichnungen ihres Volkes im Schnee begraben liegen.]=],
		},
	},
})

Translate("deDE", "gol-bolar-quarry", {
	title = "Der Gol'bolar Steinbruch",
	aliases = { "Gol'bolar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Gol'bolar Steinbruch ist eine große offene Grube im Osten von {link:dun-morogh}Dun Morogh{/link}, in der die Bergleute des Königs Erz und Stein brechen. Als sie tief gruben, strömten die {link:troggs}Troggs{/link} der Rockjaw aus dem Fels, zertrümmerten die Maschinen und vertrieben die Bergleute aus der Grube. Nun tobt der Vorarbeiter, ein Senator von {link:ironforge}Ironforge{/link} bezahlt für Troggköpfe, und der Steinbruchmeister hofft, dass niemand erfährt, dass die Troggs mit seinem Sprengpulver davongelaufen sind. Von den Tundrid-Hügeln darüber wacht ein Fremder der Wildhammer über alles.]=],
		},
	},
})

Translate("deDE", "amberstill-ranch", {
	title = "Amberstill-Ranch",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Amberstill-Ranch liegt an der Straße östlich von {link:kharanos}Kharanos{/link}. Die Familie Amberstill züchtet die großen Bergwidder, die die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link} tragen, und ihre Herden sind der Stolz von {link:dun-morogh}Dun Morogh{/link}. Widder von der Ranch gehen nun an die Expedition in {link:alterac-mountains}Alterac{/link}, und sie brauchen Sättel aus den feinsten Leopardenfellen. Die Herde hat auch einen eigenen Jäger gefunden: die Bestie {link:vagash}Vagash{/link}, die an den Hängen darüber haust und nachts herabkommt.]=],
		},
	},
})

Translate("deDE", "misty-pine-refuge", {
	title = "Nebelfichtenzuflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nebelfichtenzuflucht ist ein einsames Haus in den nördlichen Hügeln von {link:dun-morogh}Dun Morogh{/link}, östlich der Tore von {link:ironforge}Ironforge{/link}. {link:father-gavin}Vater Gavin{/link} von der {link:argent-dawn}Argentumdämmerung{/link} hat es ausgebessert und hält sein Herdfeuer für jeden Reisenden am Brennen, den die Kälte überrascht. Die Berge ringsum sind gefährlich geworden. Ein Steinschlag von den Gipfeln hat Eisgeister aufgestört, und der größte von ihnen scheint, wohin er auch geht, Stürme und neue Steinschläge zu bringen.]=],
		},
	},
})

Translate("deDE", "helm-s-bed-lake", {
	title = "Helmsbedsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Helmsbedsee liegt im äußersten Südosten von {link:dun-morogh}Dun Morogh{/link}, nahe den Pässen nach {link:loch-modan}Loch Modan{/link}. Sein Wasser ist größtenteils gefroren, und das Land ringsum ist wild und leer. {link:troggs}Troggs{/link} der Rockjaw streifen an seinen Ufern umher. In den Hügeln im Norden wartet ein Belagerungspilot neben zwei Maschinen auf einen Freund, der allein weiterzog, um nach seltenem Erz zu suchen. Der Freund war Mori Hildelve, und ein großer Bär namens Mangeclaw fand ihn zuerst.]=],
		},
	},
})

Translate("deDE", "ironband-s-compound", {
	title = "Ironbands Truppenlager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ironbands Truppenlager ist ein Haus mit Hof südlich des Helmsbedsees, im Osten von {link:dun-morogh}Dun Morogh{/link}. Seine zwergischen Besitzer haben es verlassen. {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} halten es nun, angeführt von einem Hauptmann namens Beld, und sie greifen jeden an, der sich nähert. Der {link:earthseer-farsen}Erdseher Farsen{/link} von den Wildhammer glaubt, dass sie keine bloßen Plünderer sind. Karten, die man ihren Toten abnahm, zeigen Tunnel, die weit unter der Erde verlaufen und sich unter {link:ironforge}Ironforge{/link} treffen.]=],
		},
	},
})

Translate("deDE", "frostmane-trolls", {
	title = "Trolle der Frostmane",
	aliases = { "Frostmane", "Frostmane-Trolle", "Stamm der Frostmane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Frostmane sind ein Stamm von {link:trolls}Trollen{/link}, der im Schnee von {link:dun-morogh}Dun Morogh{/link} lebt. Sie sind wild und verschlossen, und sie streiten mit den Zwergen um diese Berge. Keine Chronik verzeichnet, wann sie zuerst hierherkamen.]=],
		},
		{
			title = "Ihre Lande",
			text = [=[Ihre größte Festung ist die {link:frostmane-hold}Höhle der Frostmane{/link}, eine Höhle südwestlich von {link:brewnall-village}Brewnall{/link}. Sie haben auch Lager auf dem {link:shimmer-ridge}Schimmergrat{/link} und eine Höhle im Süden des Coldridgetals, in der die Jungen des Stammes leben. Ihre Krieger sind Kopfjäger und Schneeläufer. Ihre Seher und Schattenwirker wirken eine eigene Magie, und sie sammeln Schimmerkraut für ihre Rituale.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Senat von {link:ironforge}Ironforge{/link} hat mit den {link:troggs}Troggs{/link} alle Hände voll zu tun, und er würde lieber gar nicht an die {link:trolls}Trolle{/link} denken. Zwei Brüder der Familie Whitebeard wurden ausgesandt, um zu erfahren, wie groß die Bedrohung wirklich ist. {link:grelin-whitebeard}Grelin{/link} befand, die Trolle von {link:coldridge-valley}Coldridge{/link} seien wenige. {link:senir-whitebeard}Senir{/link} fand die {link:frostmane-hold}Höhle der Frostmane{/link} voll von ihnen. Zwischen den beiden Berichten liegt die Frage, wie viel die {link:dwarves}Zwerge{/link} sich leisten können zu übersehen. In Coldridge hat ein Troll namens {link:grik-nir-the-cold}Grik'nir der Kalte{/link} den Zwergen mehr gestohlen als ein Tagebuch: Er hat ihnen gezeigt, dass die Frostmane sie beobachten.]=],
		},
	},
})

Translate("deDE", "gnomeregan-exiles", {
	title = "Gnomeregangnome",
	aliases = { "Verbannte von Gnomeregan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Gnomeregangnome sind die {link:gnomes}Gnome{/link}, die den Fall ihrer Stadt überlebten. Sie sind ein Volk ohne Heimat. Die meisten von ihnen leben in {link:ironforge}Ironforge{/link}, wo König {link:magni-bronzebeard}Magni Bronzebeard{/link} ihnen in {link:tinker-town}Tinker Town{/link} Platz gab, doch sie sind über {link:dun-morogh}Dun Morogh{/link} und darüber hinaus verstreut.]=],
		},
		{
			title = "Nach dem Fall",
			text = [=[Die {link:troggs}Troggs{/link} kamen unter {link:gnomeregan}Gnomeregan{/link} herauf, und die {link:gnomes}Gnome{/link} trieben sie mit einer Waffe aus eigener Herstellung zurück. Es ging furchtbar schief. Die Stadt wurde vergiftet, und viele ihrer Bewohner wurden in kranke und geistlose Lepragnome verwandelt, die noch immer vor ihren Toren umherirren. Die übrigen flohen mit allem, was sie tragen konnten, in den Schnee. Manche verloren unterwegs alles an die {link:trolls}Trolle{/link}. Andere ließen die Aufzeichnungen ihrer Familien, ihrer Erfindungen und ihres Handwerks zurück.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Verbannten haben nicht aufgegeben. In {link:kharanos}Kharanos{/link} bauen {link:razzle-sprysprocket}Razzle Sprysprocket{/link} und Ozzie Togglevolt eine Maschine, von der sie hoffen, dass sie die vergifteten {link:gnomes}Gnome{/link} wiederherstellen wird. In {link:ironforge}Ironforge{/link} senden die Tüftler von {link:gnomeregan}Gnomeregan{/link} mutige Fremde zurück in die Stadt, um ihr verlorenes Wissen zu retten. Hochtüftler {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} schwört, dass sein Volk seine Heimat dem Verräter, der sie hält, wieder entreißen wird.]=],
		},
	},
})

Translate("deDE", "sten-stoutarm", {
	title = "Sten Stoutarm",
	subtitle = "Ausstatter von Coldridge",
	found = "Vor den Toren von Anvilmar",
	hint = [=[Sprecht mit dem Zwerg, der Neuankömmlinge vor den Toren von Anvilmar begrüßt.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Stoutarm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sten Stoutarm hält Wache vor den Toren von Anvilmar und begrüßt jene, die nach {link:coldridge-valley}Coldridge{/link} kommen, um zu dienen. Er hat eine praktische Art, sie willkommen zu heißen. Ein Paar warmer Handschuhe ist sein erstes Geschenk, und Wolfsfleisch ist sein Preis. In einem so kalten Tal, meint er, ist es besser, eine Morgenjagd zu verlieren als einen Finger.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sten ist der erste {link:dwarves}Zwerg{/link}, dem die meisten Neuankömmlinge in {link:coldridge-valley}Coldridge{/link} begegnen. Er schickt Briefe die Straße hinunter und sorgt dafür, dass kein Rekrut von {link:ironforge}Ironforge{/link} unvorbereitet in den Schnee hinauszieht.]=],
		},
	},
	mentions = {
		{ text = "Zwergische Ausstatter" },
		{ text = "Postzustellung im Coldridgetal" },
	},
	bonds = {
		{ id = "balir-frosthammer", name = "Balir Frosthammer", note = "hält neben ihm Wache" },
		{ id = "grelin-whitebeard", name = "Grelin Whitebeard", note = "erhält die Post des Tals" },
	},
})

Translate("deDE", "balir-frosthammer", {
	title = "Balir Frosthammer",
	subtitle = "Verteidiger von Coldridge",
	found = "Vor den Toren von Anvilmar",
	hint = [=[Sprecht mit dem Zwerg in Anvilmar, der sich um die Troggs sorgt.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Balir" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Balir Frosthammer steht in Anvilmar, und die {link:troggs}Troggs{/link} gehen ihm nicht aus dem Sinn. Sie sind in den Hügeln im Südosten und rund um den gefrorenen See aufgetaucht, und erst vor wenigen Nächten überrannten sie das Lager der {link:dwarves}Zwerge{/link} im Westen des Tals. Balir fehlt es an starken Armen, und er nimmt jeden, den er bekommen kann.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Balir blickt über sein eigenes Tal hinaus. Wenn {link:coldridge-valley}Coldridge{/link} irgendein Zeichen dafür ist, was überall in {link:dun-morogh}Dun Morogh{/link} geschieht, so fürchtet er, stehen harte Zeiten bevor, und er hofft, dass der König und der Senat darauf vorbereitet sind.]=],
		},
	},
	mentions = {
		{ text = "Eine neue Bedrohung" },
	},
	bonds = {
		{ id = "sten-stoutarm", name = "Sten Stoutarm", note = "hält neben ihm Wache" },
	},
})

Translate("deDE", "felix-whindlebolt", {
	title = "Felix Whindlebolt",
	subtitle = "Flüchtling aus Gnomeregan",
	found = "Anvilmar",
	hint = [=[Sucht den gnomischen Flüchtling, der in Anvilmar Zuflucht gefunden hat.]=],
	allegiance = "Gnomeregangnome",
	aliases = { "Felix" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Felix Whindlebolt ist ein {link:gnomes}Gnom{/link}, der vor dem Gift von {link:gnomeregan}Gnomeregan{/link} mit nichts als seinem Leben floh. Unterwegs nahmen ihm die {link:frostmane-trolls}Trolle der Frostmane{/link} den Rest: seine Truhe, seine Kiste und sogar seinen Eimer voller Bolzen. Nun hat er in Anvilmar Zuflucht gefunden und gibt freimütig zu, dass er kein Kämpfer ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Felix erzählt den Fall seiner Stadt in wenigen schlichten Worten: Die {link:gnomes}Gnome{/link} vertrieben die {link:troggs}Troggs{/link}, und dann ging alles furchtbar schief. Seine kleinen Verluste stehen für einen großen.]=],
		},
	},
	mentions = {
		{ text = "Das Dilemma eines Flüchtlings" },
	},
	bonds = {
		{ id = "grik-nir-the-cold", name = "Grik'nir der Kalte", note = "seine Trolle nahmen Felix' Sachen" },
	},
})

Translate("deDE", "grelin-whitebeard", {
	title = "Grelin Whitebeard",
	subtitle = "Beobachter der Frostmane",
	found = "Sein Lager im Südosten des Coldridgetals",
	hint = [=[Sucht den Zwerg, der die Trolle von seinem Lager im Coldridgetal aus studiert.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Grelin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grelin Whitebeard wurde ins Coldridgetal gesandt, um zu erfahren, wie groß die Gefahr durch die {link:frostmane-trolls}Trolle der Frostmane{/link} ist. Sein Bruder {link:senir-whitebeard}Senir{/link} wurde mit demselben Auftrag nach {link:kharanos}Kharanos{/link} gesandt. Grelin befand, dass die {link:trolls}Trolle{/link} des Tals wenige seien und das Heer nicht gebraucht werde. Die Trolle antworteten, indem sie ihm in der Nacht sein Tagebuch stahlen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Grelins Bericht, durch die {link:troggs}Troggs{/link} des Coldridgepasses zu seinem Bruder gebracht, ist eines der Stücke, aus denen der Senat die Bedrohung durch die {link:trolls}Trolle{/link} beurteilen muss.]=],
		},
	},
	chapters = {
		{
			title = "Das gestohlene Tagebuch",
			hint = "Holt zurück, was die Trolle Grelin genommen haben.",
			text = [=[Der Dieb war ein großer Troll mit seltsamen Zeichen auf Gesicht und Haut. Als das Tagebuch zurückkam, konnte Grelin seine Arbeit beenden und die Trollplage des Tals für gut unter Kontrolle erklären. Er achtete darauf, den Bericht durch zuverlässige Hände an {link:senir-whitebeard}Senir{/link} zu senden, nicht durch seinen Lehrling.]=],
		},
	},
	mentions = {
		{ text = "Postzustellung im Coldridgetal" },
		{ text = "Die Trollhöhle" },
		{ text = "Das gestohlene Tagebuch" },
		{ text = "Senirs Beobachtungen" },
	},
	bonds = {
		{ id = "senir-whitebeard", name = "Senir Whitebeard", note = "sein Bruder" },
		{ id = "grik-nir-the-cold", name = "Grik'nir der Kalte", note = "stahl sein Tagebuch" },
		{ id = "sten-stoutarm", name = "Sten Stoutarm", note = "schickt ihm seine Briefe" },
	},
})

Translate("deDE", "grik-nir-the-cold", {
	title = "Grik'nir der Kalte",
	subtitle = "Troll der Höhle von Coldridge",
