	subtitle = "Berichterstatter von Kharanos",
	found = "Kharanos",
	hint = [=[Sucht den Zwerg in Kharanos, der mit seinem Bericht im Rückstand ist.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Senir" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Senir Whitebeard beobachtet die {link:trolls}Trolle{/link} von {link:kharanos}Kharanos{/link} aus und schreibt Berichte für {link:ironforge}Ironforge{/link}, auch wenn er mit ihnen immer ein wenig im Rückstand ist. Er fand die {link:frostmane-hold}Höhle der Frostmane{/link}, doch er wagte nicht hineinzugehen. Mit seiner Feder ist er kühner. Seine Berichte beanspruchen für seine Arbeit die Autorität des Königs selbst, und das gefällt dem Senat nicht.]=],
