	chapters = {
		{
			title = "Die Berichte",
			hint = "Bringt Senirs Bericht zum Senat in Ironforge.",
			text = [=[Senir schickte seinen fertigen Bericht nach {link:ironforge}Ironforge{/link}, mit der Warnung, dass dessen Leser ein griesgrämiger Kerl sei, und mit der Hoffnung, dass niemand erfahren würde, wer seine Arbeit für ihn erledigt hatte. Senator Redstone las, dass im Feld Magnis Autorität beansprucht wurde, und verlangte zu wissen, ob der König den Verstand verloren habe.]=],
		},
	},
	mentions = {
		{ text = "Senirs Beobachtungen" },
		{ text = "Die {link:frostmane-hold}Höhle der Frostmane{/link}" },
		{ text = "Die Berichte" },
		{ text = "Sichert den Berg" },
	},
	bonds = {
