	aliases = { "Gretchen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gretchen ist eine Gebirgsjägerin von {link:ironforge}Ironforge{/link}, die ausgesandt wurde, um zu erfahren, warum sich die Wendigos ausbreiten. Ihr Partner Cornelius stürmte vor ihr in den altgedienten Bau und kehrte nicht zurück. Gretchen hielt die Höhle für verloren und weigerte sich, noch jemanden hineinzuschicken, um dort zu sterben. Sie wird ihren Posten nicht verlassen, bis der Berg sicher ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gretchens Bericht sagt {link:kharanos}Kharanos{/link}, was es nicht hören wollte: Eine seiner besten Erzquellen ist an die Wendigos verloren, und der Berg ist noch nicht sicher.]=],
		},
	},
	mentions = {
		{ text = "Sichert den Berg" },
		{ text = "Sichert den Berg" },
